import{_ as s,C as i,o as t,c as d,a2 as o,b as l,w as a,a as p,E as c,a3 as n}from"./chunks/framework.DZUUNQ77.js";const f=JSON.parse('{"title":"SystemPropertiesCompat · 系统属性兼容","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/compat/system-properties-compat.md","filePath":"reference/helper/compat/system-properties-compat.md","lastUpdated":1784053534000}'),m={name:"reference/helper/compat/system-properties-compat.md"};function h(u,e,A,E,b,S){const r=i("Mermaid");return t(),d("div",null,[e[1]||(e[1]=o('<h1 id="systempropertiescompat-·-系统属性兼容" tabindex="-1">SystemPropertiesCompat · 系统属性兼容 <a class="header-anchor" href="#systempropertiescompat-·-系统属性兼容" aria-label="Permalink to &quot;SystemPropertiesCompat · 系统属性兼容&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/compat/SystemPropertiesCompat.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/compat/SystemPropertiesCompat.java</code></a></p></div><p><code>SystemPropertiesCompat</code> 用反射封装隐藏类 <code>android.os.SystemProperties</code>，提供读取 <code>ro.build.*</code> 等系统属性的能力。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>get(String key, String defaultValue)</code></td><td>取属性值，不存在返回默认值</td></tr></tbody></table><h2 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h2><ul><li>懒加载 <code>Class&lt;?&gt; sClass</code>（<code>Class.forName(&quot;android.os.SystemProperties&quot;)</code>）。</li><li><code>getInner</code> 反射调用 <code>SystemProperties.get(String, String)</code> 静态方法。</li><li>取不到类或方法失败时返回 <code>defaultValue</code>，不抛异常。</li></ul><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p><code>SystemProperties</code> 是 <code>@hide</code> 的，普通 App 不能直接 <code>import</code>。但框架多处需要读属性：<a href="./../utils/os-utils"><code>OSUtils</code></a> 读 <code>ro.miui.ui.version.code</code> 判定 ROM、native 层读 <code>ro.product.cpu.abi</code> 选 hook 实现。本类把这些反射调用收敛到一处。</p><h2 id="与设备伪造的关系" tabindex="-1">与设备伪造的关系 <a class="header-anchor" href="#与设备伪造的关系" aria-label="Permalink to &quot;与设备伪造的关系&quot;">​</a></h2><p>注意：本类读的是<strong>真实</strong>系统属性。设备信息<strong>伪造</strong>是在更上层——<a href="./../../proxies/os">os 代理</a> 拦截 <code>Build</code> / <code>SystemProperties.get</code> 调用并返回伪造值，而本类是框架内部读真实属性的底座。</p><h2 id="真实属性-vs-伪造" tabindex="-1">真实属性 vs 伪造 <a class="header-anchor" href="#真实属性-vs-伪造" aria-label="Permalink to &quot;真实属性 vs 伪造&quot;">​</a></h2>',12)),(t(),l(n,null,{default:a(()=>[c(r,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20REAL%5B%22%E6%A1%86%E6%9E%B6%E5%86%85%E9%83%A8%E8%AF%BB%E7%9C%9F%E5%AE%9E%E5%B1%9E%E6%80%A7%22%5D%0A%20%20%20%20SPC%5B%22SystemPropertiesCompat%3Cbr%2F%3E%E5%8F%8D%E5%B0%84%20SystemProperties.get%22%5D%0A%20%20%20%20SPC%20--%3E%20OSU%5B%22OSUtils%20%E8%AF%BB%20ro.miui.*%22%5D%0A%20%20%20%20SPC%20--%3E%20NAT%5B%22native%20%E8%AF%BB%20ro.product.cpu.abi%22%5D%0A%20%20end%0A%20%20subgraph%20FAKE%5B%22%E5%AF%B9%E7%9B%AE%E6%A0%87%20App%20%E4%BC%AA%E9%80%A0%22%5D%0A%20%20%20%20OSP%5B%22os%20%E4%BB%A3%E7%90%86%20%E6%8B%A6%E6%88%AA%3Cbr%2F%3EBuild%20%2F%20SystemProperties.get%22%5D%0A%20%20%20%20OSP%20--%3E%20APP%5B%22%E7%9B%AE%E6%A0%87%20App%20%E7%9C%8B%E5%88%B0%E4%BC%AA%E9%80%A0%E5%80%BC%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>两个层次互不干扰：框架判定 ROM/架构用真实属性，目标 App 看到的是伪造值。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../utils/os-utils"><code>OSUtils</code></a>：ROM 识别依赖它读 build.prop property。</li><li><a href="./../../proxies/os">os 代理</a>：设备标识伪造。</li><li><a href="/VirtualXposed-skills/features/device-spoofing">设备信息伪造</a>。</li></ul>',3))])}const _=s(m,[["render",h]]);export{f as __pageData,_ as default};
